CREATE TYPE "ExamStatus" AS ENUM ('OPEN', 'CLOSED');
CREATE TYPE "ExamApplicationStatus" AS ENUM ('DRAFT', 'READY_FOR_SUBMISSION', 'SUBMITTED', 'PAYMENT_CONFIRMED', 'ACCEPTED', 'CORRECTION_WINDOW', 'ADMIT_CARD_AVAILABLE', 'EXAM_COMPLETED', 'ANSWER_KEY_AVAILABLE', 'RESULT_AVAILABLE');
CREATE TYPE "ExamPaymentStatus" AS ENUM ('NOT_STARTED', 'PROCESSING', 'SUCCESSFUL');
CREATE TYPE "ExamDocumentSource" AS ENUM ('MOCK_ISSUED_DOCUMENT');

CREATE TABLE "government_exams" ("government_exam_id" UUID NOT NULL, "slug" VARCHAR(120) NOT NULL, "name" VARCHAR(250) NOT NULL, "conducting_authority" VARCHAR(250) NOT NULL, "description" TEXT NOT NULL, "status" "ExamStatus" NOT NULL DEFAULT 'OPEN', "application_start_date" DATE NOT NULL, "application_end_date" DATE NOT NULL, "application_fee_paise" INTEGER NOT NULL, "eligibility" TEXT NOT NULL, "exam_date" DATE NOT NULL, "vacancy_count" INTEGER NOT NULL, "notification_content" JSONB NOT NULL, "is_demo" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "government_exams_pkey" PRIMARY KEY ("government_exam_id"));
CREATE UNIQUE INDEX "government_exams_slug_key" ON "government_exams"("slug");
CREATE TABLE "exam_requirements" ("exam_requirement_id" UUID NOT NULL, "government_exam_id" UUID NOT NULL, "name" VARCHAR(200) NOT NULL, "document_type" VARCHAR(150) NOT NULL, "is_required" BOOLEAN NOT NULL DEFAULT true, "sort_order" INTEGER NOT NULL DEFAULT 0, "issuable_service_slug" VARCHAR(100), CONSTRAINT "exam_requirements_pkey" PRIMARY KEY ("exam_requirement_id"));
CREATE UNIQUE INDEX "exam_requirements_government_exam_id_name_key" ON "exam_requirements"("government_exam_id", "name");
CREATE TABLE "exam_applications" ("exam_application_id" UUID NOT NULL, "application_number" VARCHAR(100) NOT NULL, "citizen_id" UUID NOT NULL, "government_exam_id" UUID NOT NULL, "status" "ExamApplicationStatus" NOT NULL DEFAULT 'DRAFT', "payment_status" "ExamPaymentStatus" NOT NULL DEFAULT 'NOT_STARTED', "form_data" JSONB, "submitted_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "exam_applications_pkey" PRIMARY KEY ("exam_application_id"));
CREATE UNIQUE INDEX "exam_applications_application_number_key" ON "exam_applications"("application_number");
CREATE UNIQUE INDEX "exam_applications_citizen_id_government_exam_id_key" ON "exam_applications"("citizen_id", "government_exam_id");
CREATE INDEX "exam_applications_citizen_id_updated_at_idx" ON "exam_applications"("citizen_id", "updated_at");
CREATE TABLE "exam_application_documents" ("exam_application_document_id" UUID NOT NULL, "exam_application_id" UUID NOT NULL, "exam_requirement_id" UUID NOT NULL, "mock_issued_document_id" UUID NOT NULL, "source" "ExamDocumentSource" NOT NULL DEFAULT 'MOCK_ISSUED_DOCUMENT', "attached_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_application_documents_pkey" PRIMARY KEY ("exam_application_document_id"));
CREATE UNIQUE INDEX "exam_application_documents_exam_application_id_exam_requirement_id_key" ON "exam_application_documents"("exam_application_id", "exam_requirement_id");
CREATE TABLE "exam_timeline_events" ("exam_timeline_event_id" UUID NOT NULL, "exam_application_id" UUID NOT NULL, "event_type" VARCHAR(100) NOT NULL, "title" VARCHAR(200) NOT NULL, "description" TEXT NOT NULL, "target_date" DATE NOT NULL, "status" VARCHAR(50) NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "exam_timeline_events_pkey" PRIMARY KEY ("exam_timeline_event_id"));
CREATE INDEX "exam_timeline_events_exam_application_id_sort_order_idx" ON "exam_timeline_events"("exam_application_id", "sort_order");
CREATE TABLE "exam_reminders" ("exam_reminder_id" UUID NOT NULL, "exam_application_id" UUID NOT NULL, "reminder_type" VARCHAR(100) NOT NULL, "target_date" DATE NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_reminders_pkey" PRIMARY KEY ("exam_reminder_id"));
CREATE UNIQUE INDEX "exam_reminders_exam_application_id_key" ON "exam_reminders"("exam_application_id");
ALTER TABLE "exam_requirements" ADD CONSTRAINT "exam_requirements_government_exam_id_fkey" FOREIGN KEY ("government_exam_id") REFERENCES "government_exams"("government_exam_id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "exam_applications" ADD CONSTRAINT "exam_applications_citizen_id_fkey" FOREIGN KEY ("citizen_id") REFERENCES "citizen_profiles"("citizen_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "exam_applications" ADD CONSTRAINT "exam_applications_government_exam_id_fkey" FOREIGN KEY ("government_exam_id") REFERENCES "government_exams"("government_exam_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "exam_application_documents" ADD CONSTRAINT "exam_application_documents_exam_application_id_fkey" FOREIGN KEY ("exam_application_id") REFERENCES "exam_applications"("exam_application_id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "exam_application_documents" ADD CONSTRAINT "exam_application_documents_exam_requirement_id_fkey" FOREIGN KEY ("exam_requirement_id") REFERENCES "exam_requirements"("exam_requirement_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "exam_application_documents" ADD CONSTRAINT "exam_application_documents_mock_issued_document_id_fkey" FOREIGN KEY ("mock_issued_document_id") REFERENCES "mock_issued_documents"("mock_issued_document_id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "exam_timeline_events" ADD CONSTRAINT "exam_timeline_events_exam_application_id_fkey" FOREIGN KEY ("exam_application_id") REFERENCES "exam_applications"("exam_application_id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "exam_reminders" ADD CONSTRAINT "exam_reminders_exam_application_id_fkey" FOREIGN KEY ("exam_application_id") REFERENCES "exam_applications"("exam_application_id") ON DELETE CASCADE ON UPDATE CASCADE;
